<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';
$message='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$sql=file_get_contents(__DIR__.'/database/database.sql');$pdo=db();$pdo->exec($sql);$hash=password_hash((string)$_POST['password'],PASSWORD_DEFAULT);$exists=dbone('SELECT id FROM admins WHERE email=?',[trim($_POST['email'])]);if($exists){dbq('UPDATE admins SET name=?,username=?,password=?,status=1 WHERE id=?',[trim($_POST['name']),trim($_POST['username']),$hash,$exists['id']]);}else{dbq('INSERT INTO admins(name,username,email,password,status,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())',[trim($_POST['name']),trim($_POST['username']),trim($_POST['email']),$hash]);}if(!dbone('SELECT id FROM basic_settings LIMIT 1')) dbq("INSERT INTO basic_settings(sitename,currency,currency_sym,registration,login,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())",[APP_NAME,'NGN','₦',1,1]);$message='Installation completed. You can now log in.';$done=true;}catch(Throwable $e){$message='Installation error: '.$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><title>Install · <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="login card"><h1>Install <?=e(APP_NAME)?></h1><?php if($message):?><div class="alert <?= $done?'success':'danger' ?>"><?=e($message)?></div><?php endif;?><?php if(!$done):?><form method="post"><?=csrf_field()?><div class="field"><label>Admin name</label><input name="name" required></div><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" minlength="8" required></div><br><button class="btn">Install</button></form><?php else:?><a class="btn" href="login.php">Go to login</a><?php endif;?></div></body></html>
